                read_count <= read_count + 6'd1;
                if (read_count == 6'd31) begin
                    read_pending <= 1'b0;
                    fault_active <= 1'b0;
                end
            end
            // Extraction MOSI is deliberately excluded from ingress qualification.
        end
    end
